"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-1069-01-01:0":{"b": ["Regno di Kush — periodo di Napata: inizia", "fd21e916"], "d": ["Periodo della dinastia di Kush con centro a Napata; il centro si sposta a Meroe nel ~300 a.C. In questo periodo si colloca la XXV dinastia (Kush), che conquistò l'Egitto — le date della XXV dinastia NON sono in questa fonte.", "b8938f36"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-1449-01-01:0":{"b": ["Regno/cultura di Kerma (Kush): termina", "95c2812c"], "d": ["Regno nubiano con centro a Kerma, sotto la Terza Cateratta; passato per le fasi Kerma antico (~2500), medio, classico, termina nel ~1450 a.C. Honegger 2005: «Kerma Classique (vers 1500 av. J.-C.)» insediamento fortificato.", "5ea1ab25"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-1499-01-01:0":{"b": ["Napata (Gebel Barkal): inizia", "fbf16715"], "d": ["Fondata come avamposto fortificato dell'Egitto nel Nuovo Regno; città principale della dinastia di Kush (periodo napateo 1070–300 a.C.), mantenne la sua importanza durante il periodo di Meroe (300 a.C.–350 d.C.).", "a384d267"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-1556-01-01:0":{"b": ["Nuovo Regno (inizio della XVIII dinastia con Ahmose I): inizia", "0472735f"], "d": ["L'ascesa al trono di Ahmose I (inizio della XVIII dinastia/Nuovo Regno) si colloca nel modello di Bronk Ramsey e coll. tra il 1570 e il 1544 a.C. (2σ).", "13b3514b"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-1811-01-01:0":{"b": ["Medio Regno: termina", "51fa178c"], "d": ["Seconda grande fase di unità dell'Egitto; l'articolo sostiene la cronologia «alta» (rifiuta quella «bassa»), con il periodo di Sesostri III misurato tramite gli anelli di crescita delle travi della fortezza di Uronarti (Sudan).", "e792785c"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-2050-01-01:0":{"b": ["Primo Periodo Intermedio: termina", "7e2d8fc1"], "d": ["Periodo frammentato che va dalla dissoluzione dell'autorità centrale dell'Antico Regno all'inizio del Medio Regno; l'articolo sottolinea la coerenza con l'evento di siccità di 4,2 ka (circa 2250 a.C.).", "47a3a1aa"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-2050-01-01:1":{"b": ["Medio Regno: inizia", "0e85ade1"], "d": ["Seconda grande fase di unità dell'Egitto; l'articolo sostiene la cronologia «alta» (rifiuta quella «bassa»), con il periodo di Sesostri III misurato tramite gli anelli di crescita delle travi della fortezza di Uronarti (Sudan).", "e792785c"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-2242-01-01:0":{"b": ["Antico Regno (Età delle Piramidi): termina", "65237d84"], "d": ["Regno dell'Età delle Piramidi; secondo Erdil e coll. 2025 l'inizio dell'Antico Regno cade nel 2698–2629 a.C. circa (95%), il passaggio al Primo Periodo Intermedio nel 2283–2204 a.C. circa (95%). La cronologia «bassa» non è più sostenibile in questo intervallo.", "2ac5035a"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-2242-01-01:1":{"b": ["Primo Periodo Intermedio: inizia", "ef148434"], "d": ["Periodo frammentato che va dalla dissoluzione dell'autorità centrale dell'Antico Regno all'inizio del Medio Regno; l'articolo sottolinea la coerenza con l'evento di siccità di 4,2 ka (circa 2250 a.C.).", "47a3a1aa"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-2499-01-01:0":{"b": ["Regno/cultura di Kerma (Kush): inizia", "f7cdc981"], "d": ["Regno nubiano con centro a Kerma, a valle della Terza Cataratta; attraversa le fasi di Kerma antico (~2500), medio e classico e termina intorno al 1450 a.C. Honegger 2005: «Kerma Classique (vers 1500 av. J.-C.)», insediamento fortificato.", "5ea1ab25"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-2662-01-01:0":{"b": ["Antico Regno (Età delle Piramidi): inizia", "9e3a1499"], "d": ["Regno dell'Età delle Piramidi; secondo Erdil e coll. 2025 l'inizio dell'Antico Regno cade nel 2698–2629 a.C. circa (95%), il passaggio al Primo Periodo Intermedio nel 2283–2204 a.C. circa (95%). La cronologia «bassa» non è più sostenibile in questo intervallo.", "2ac5035a"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-3125-01-01:0":{"b": ["Cultura di Naqada: termina", "a6d98d7b"], "d": ["Cultura predinastica dell'Alto Egitto successiva a quella badariana; comprende le fasi Naqada I-III e con Naqada IIIC giunge all'unità politica con la I dinastia (Aha).", "8fadb99a"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-3499-01-01:0":{"b": ["Cultura di Pre-Kerma: inizia", "35f09768"], "d": ["Cultura della regione di Kerma (ramo di Dongola/a valle della Terza Cataratta del Nilo) che segna il passaggio dal Neolitico a Kerma, con fosse per lo stoccaggio agricolo e segni di precoce complessità sociale.", "f9a036cb"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-3755-01-01:0":{"b": ["Cultura di Naqada: inizia", "1960a726"], "d": ["Cultura predinastica dell'Alto Egitto successiva a quella badariana; comprende le fasi Naqada I-III e con Naqada IIIC giunge all'unità politica con la I dinastia (Aha).", "8fadb99a"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-3949-01-01:0":{"b": ["Riparo roccioso di Takarkori (Tadrart Acacus): termina", "845c6a70"], "d": ["Riparo roccioso nel Tadrart Acacus, nel Fezzan libico: stratigrafia ininterrotta che va dai cacciatori-raccoglitori-pescatori dell'Acacus tardo (primo insediamento LA1) ai pastori del Pastorale antico, medio e tardo (Sahara verde).", "29888604"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-4699-01-01:0":{"b": ["Neolitico di Shaheinab: inizia", "7a9cfd9c"], "d": ["Insediamento neolitico del Sudan centrale vicino al Nilo (animali domestici, ceramica, sgorbie); definisce come sito-tipo il «Neolitico di Shaheinab». L'intervallo generale della cultura è 5000–3800 a.C.", "cd4d3a3c"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-4849-01-01:0":{"b": ["Insediamento olocenico del Fayum (attorno al lago Qarun): termina", "53ff4e34"], "d": ["Nel Fayum insediamento olocenico di pescatori-cacciatori dal 7350 a.C. circa; piante e animali domestici dal 5400 a.C. circa; gli insediamenti neolitici di Kom K/W datano al 4850–4250 a.C.", "a016950f"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-4999-01-01:0":{"b": ["Khartoum antico (Mesolitico di Khartoum): termina", "89b30a20"], "d": ["Mesolitico di cacciatori-raccoglitori-pescatori con ceramica (a linee ondulate) sulle rive del Nilo nel Sudan centrale; denominato da Arkell «Khartoum Mesolithic»/«Early Khartoum».", "7c5ed92c"]},
